'use client';

interface ContentPreviewProps {
  content: string;
  summary?: string;
  qualityScore?: number;
  wordCount?: number;
  platform?: string;
  onCopy: () => void;
}

export function ContentPreview({
  content,
  summary,
  qualityScore,
  wordCount,
  platform,
  onCopy,
}: ContentPreviewProps) {
  return (
    <div className="card" style={{ marginTop: '1.5rem' }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '0.75rem',
          marginBottom: '1rem',
        }}
      >
        <h3 style={{ fontSize: '1rem' }}>Generated preview</h3>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          {platform && (
            <span
              style={{
                fontSize: '0.75rem',
                padding: '0.2rem 0.6rem',
                borderRadius: 999,
                background: 'var(--bg)',
                border: '1px solid var(--border)',
              }}
            >
              {platform}
            </span>
          )}
          {qualityScore != null && (
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
              Quality: {qualityScore}/100
            </span>
          )}
          {wordCount != null && (
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
              {wordCount} words
            </span>
          )}
        </div>
      </div>

      {summary && (
        <details style={{ marginBottom: '1rem' }}>
          <summary style={{ cursor: 'pointer', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
            Article summary
          </summary>
          <p style={{ marginTop: '0.5rem', fontSize: '0.9rem', color: 'var(--text-muted)' }}>
            {summary}
          </p>
        </details>
      )}

      <pre
        style={{
          whiteSpace: 'pre-wrap',
          wordBreak: 'break-word',
          fontFamily: 'inherit',
          fontSize: '0.95rem',
          lineHeight: 1.6,
          padding: '1rem',
          background: 'var(--bg)',
          borderRadius: 8,
          border: '1px solid var(--border)',
          maxHeight: 400,
          overflow: 'auto',
        }}
      >
        {content}
      </pre>

      <button
        type="button"
        className="btn btn-primary"
        style={{ marginTop: '1rem' }}
        onClick={onCopy}
      >
        Copy to clipboard
      </button>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { toast } from 'sonner';

interface Post {
  _id: string;
  websiteUrl: string;
  platform: string;
  content: string;
  qualityScore?: number;
  status: string;
  createdAt: string;
}

interface UsageData {
  user: { credits: number; plan: string };
  stats: { totalPosts: number; completedExecutions: number };
  platformBreakdown: { platform: string; count: number }[];
  analytics: { date: string; generations: number; creditsUsed: number }[];
}

export function DashboardView() {
  const [posts, setPosts] = useState<Post[]>([]);
  const [usage, setUsage] = useState<UsageData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const [historyRes, usageRes] = await Promise.all([
          fetch('/api/history?limit=10'),
          fetch('/api/usage'),
        ]);

        if (historyRes.ok) {
          const data = await historyRes.json();
          setPosts(data.posts ?? []);
        }
        if (usageRes.ok) {
          setUsage(await usageRes.json());
        }
      } catch {
        toast.error('Failed to load dashboard');
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) {
    return (
      <div className="container" style={{ padding: '2rem 0' }}>
        <div className="skeleton" style={{ height: 120, marginBottom: '1rem' }} />
        <div className="skeleton" style={{ height: 200 }} />
      </div>
    );
  }

  return (
    <div className="container" style={{ padding: '2rem 0 4rem' }}>
      <h1 style={{ fontSize: '1.75rem', marginBottom: '1.5rem' }}>Dashboard</h1>

      {usage && (
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
            gap: '1rem',
            marginBottom: '2rem',
          }}
        >
          <div className="card">
            <p style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>Credits</p>
            <p style={{ fontSize: '1.75rem', fontWeight: 700 }}>{usage.user.credits}</p>
          </div>
          <div className="card">
            <p style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>Total posts</p>
            <p style={{ fontSize: '1.75rem', fontWeight: 700 }}>{usage.stats.totalPosts}</p>
          </div>
          <div className="card">
            <p style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>Plan</p>
            <p style={{ fontSize: '1.25rem', fontWeight: 600, textTransform: 'capitalize' }}>
              {usage.user.plan}
            </p>
          </div>
        </div>
      )}

      {usage?.platformBreakdown && usage.platformBreakdown.length > 0 && (
        <div className="card" style={{ marginBottom: '2rem' }}>
          <h2 style={{ fontSize: '1rem', marginBottom: '1rem' }}>Platform usage</h2>
          <ul style={{ listStyle: 'none' }}>
            {usage.platformBreakdown.map((p) => (
              <li
                key={p.platform}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  padding: '0.4rem 0',
                  borderBottom: '1px solid var(--border)',
                  fontSize: '0.9rem',
                }}
              >
                <span style={{ textTransform: 'capitalize' }}>{p.platform}</span>
                <span>{p.count}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      <h2 style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>Recent generations</h2>
      {posts.length === 0 ? (
        <p style={{ color: 'var(--text-muted)' }}>No generations yet. Create your first post!</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          {posts.map((post) => (
            <div key={post._id} className="card">
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  marginBottom: '0.5rem',
                  flexWrap: 'wrap',
                  gap: '0.5rem',
                }}
              >
                <span style={{ fontWeight: 600, textTransform: 'capitalize' }}>
                  {post.platform}
                </span>
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: post.status === 'completed' ? 'var(--success)' : 'var(--text-muted)',
                  }}
                >
                  {post.status}
                </span>
              </div>
              <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '0.5rem' }}>
                {post.websiteUrl}
              </p>
              {post.content && (
                <p
                  style={{
                    fontSize: '0.9rem',
                    display: '-webkit-box',
                    WebkitLineClamp: 3,
                    WebkitBoxOrient: 'vertical',
                    overflow: 'hidden',
                  }}
                >
                  {post.content}
                </p>
              )}
              <button
                type="button"
                className="btn btn-ghost"
                style={{ marginTop: '0.75rem', fontSize: '0.8rem' }}
                onClick={() => {
                  if (post.content) {
                    navigator.clipboard.writeText(post.content);
                    toast.success('Copied');
                  }
                }}
              >
                Copy
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { useAuth } from '@clerk/nextjs';
import { SignInButton } from '@clerk/nextjs';
import { toast } from 'sonner';
import { PLATFORMS } from '@/lib/platforms';
import { ContentPreview } from './ContentPreview';

interface GenerateResult {
  content?: string;
  summary?: string;
  qualityScore?: number;
  wordCount?: number;
  platformName?: string;
  executionId?: string;
}

export function GenerateForm() {
  const { isSignedIn } = useAuth();
  const [websiteUrl, setWebsiteUrl] = useState('');
  const [userPrompt, setUserPrompt] = useState('');
  const [platform, setPlatform] = useState('linkedin');
  const [loading, setLoading] = useState(false);
  const [loadingStep, setLoadingStep] = useState('');
  const [result, setResult] = useState<GenerateResult | null>(null);
  const [crawlPreview, setCrawlPreview] = useState<{
    title?: string;
    description?: string;
  } | null>(null);

  const handleGenerate = useCallback(async () => {
    if (!isSignedIn) {
      toast.error('Please sign in to generate content');
      return;
    }

    if (!websiteUrl.trim() || !userPrompt.trim()) {
      toast.error('Please fill in the URL and prompt');
      return;
    }

    setLoading(true);
    setResult(null);
    setCrawlPreview(null);
    setLoadingStep('Validating & crawling...');

    try {
      const useStream = true;

      if (useStream) {
        const res = await fetch('/api/stream', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ websiteUrl, userPrompt, platform }),
        });

        if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          throw new Error(err.error ?? `Request failed (${res.status})`);
        }

        const reader = res.body?.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        if (!reader) throw new Error('No response stream');

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n\n');
          buffer = lines.pop() ?? '';

          for (const line of lines) {
            if (!line.startsWith('data: ')) continue;
            try {
              const data = JSON.parse(line.slice(6)) as {
                type: string;
                message?: string;
                title?: string;
                description?: string;
                content?: string;
                summary?: string;
                qualityScore?: number;
                wordCount?: number;
                platform?: string;
                executionId?: string;
              };

              if (data.type === 'status' && data.message) {
                setLoadingStep(data.message);
              }
              if (data.type === 'preview') {
                setCrawlPreview({
                  title: data.title,
                  description: data.description,
                });
              }
              if (data.type === 'complete') {
                setResult({
                  content: data.content,
                  summary: data.summary,
                  qualityScore: data.qualityScore,
                  wordCount: data.wordCount,
                  platformName: data.platform,
                  executionId: data.executionId,
                });
                toast.success('Content generated successfully!');
              }
              if (data.type === 'error') {
                throw new Error(data.message ?? 'Generation failed');
              }
            } catch (parseErr) {
              if (parseErr instanceof SyntaxError) continue;
              throw parseErr;
            }
          }
        }
      } else {
        const res = await fetch('/api/generate', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ websiteUrl, userPrompt, platform }),
        });

        const data = await res.json();
        if (!res.ok) throw new Error(data.error ?? 'Generation failed');

        setResult({
          content: data.content,
          summary: data.summary,
          qualityScore: data.qualityScore,
          wordCount: data.wordCount,
          platformName: data.platformName,
          executionId: data.executionId,
        });
        if (data.preview) setCrawlPreview(data.preview);
        toast.success('Content generated!');
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Something went wrong');
    } finally {
      setLoading(false);
      setLoadingStep('');
    }
  }, [isSignedIn, websiteUrl, userPrompt, platform]);

  const copyToClipboard = async () => {
    if (!result?.content) return;
    try {
      await navigator.clipboard.writeText(result.content);
      toast.success('Copied to clipboard');
    } catch {
      toast.error('Failed to copy');
    }
  };

  return (
    <section id="generate" style={{ padding: '0 0 4rem' }}>
      <div className="container" style={{ maxWidth: 640 }}>
        <div className="card">
          <h2 style={{ fontSize: '1.25rem', marginBottom: '1.25rem' }}>
            Generate social content
          </h2>

          <div className="field">
            <label className="label" htmlFor="websiteUrl">
              Website URL
            </label>
            <input
              id="websiteUrl"
              className="input"
              type="url"
              placeholder="Enter website URL to generate content from..."
              value={websiteUrl}
              onChange={(e) => setWebsiteUrl(e.target.value)}
              disabled={loading}
            />
          </div>

          <div className="field">
            <label className="label" htmlFor="userPrompt">
              Your prompt
            </label>
            <textarea
              id="userPrompt"
              className="textarea"
              placeholder="Create a LinkedIn post about this website..."
              value={userPrompt}
              onChange={(e) => setUserPrompt(e.target.value)}
              disabled={loading}
              rows={4}
            />
          </div>

          <div className="field">
            <label className="label" htmlFor="platform">
              Platform
            </label>
            <select
              id="platform"
              className="select"
              value={platform}
              onChange={(e) => setPlatform(e.target.value)}
              disabled={loading}
            >
              {PLATFORMS.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.label}
                </option>
              ))}
            </select>
          </div>

          {crawlPreview && (
            <div
              style={{
                padding: '0.75rem',
                marginBottom: '1rem',
                background: 'var(--bg)',
                borderRadius: 8,
                border: '1px solid var(--border)',
                fontSize: '0.85rem',
              }}
            >
              {crawlPreview.title && (
                <strong style={{ display: 'block' }}>{crawlPreview.title}</strong>
              )}
              {crawlPreview.description && (
                <span style={{ color: 'var(--text-muted)' }}>
                  {crawlPreview.description}
                </span>
              )}
            </div>
          )}

          {loading && (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '0.75rem',
                marginBottom: '1rem',
                color: 'var(--text-muted)',
                fontSize: '0.9rem',
              }}
            >
              <span className="spinner" />
              {loadingStep || 'Generating...'}
            </div>
          )}

          {isSignedIn ? (
            <button
              type="button"
              className="btn btn-primary"
              style={{ width: '100%' }}
              onClick={handleGenerate}
              disabled={loading}
            >
              {loading ? 'Generating...' : 'Generate content'}
            </button>
          ) : (
            <SignInButton mode="modal">
              <button type="button" className="btn btn-primary" style={{ width: '100%' }}>
                Sign in to generate
              </button>
            </SignInButton>
          )}
        </div>

        {result?.content && (
          <ContentPreview
            content={result.content}
            summary={result.summary}
            qualityScore={result.qualityScore}
            wordCount={result.wordCount}
            platform={result.platformName}
            onCopy={copyToClipboard}
          />
        )}
      </div>
    </section>
  );
}

